12433:  * heap_oos_find_vfid () - find (or optionally create) the OOS file of a heap
12434:  *   return         : true on success, false on a genuine error (er is set)
12435:  *   hfid (in)      : heap file identifier
12436:  *   oos_vfid (out) : OOS file identifier; set to NULL when the heap has no OOS
12437:  *                    file (only possible when docreate == false)
12438:  *   docreate (in)  : if true and the OOS file does not exist, it is created and
12439:  *                    TDE is applied to it (mirroring heap_ovf_find_vfid)
12440:  *
12441:  * Note: A false return ALWAYS means a real error (and er_errid () is set); it
12442:  *   never means "no OOS file". Callers using docreate == false must inspect
12443:  *   oos_vfid (VFID_ISNULL) to tell whether an OOS file actually exists.
12444:  */
12445: bool
12446: heap_oos_find_vfid (THREAD_ENTRY * thread_p, const HFID * hfid, VFID * oos_vfid, bool docreate)
12447: {
12448:   HEAP_HDR_STATS *heap_hdr;	/* Header of heap structure */
12449:   LOG_DATA_ADDR addr_hdr;	/* Address of logging data */
12450:   VPID vpid;			/* Page-volume identifier */
12451:   RECDES hdr_recdes;		/* Header record descriptor */
12452:   PGBUF_LATCH_MODE mode;
12453:   bool success;
12454: 
12455:   success = true;
12456:   VFID_SET_NULL (oos_vfid);
12457: 
12458:   addr_hdr.vfid = &hfid->vfid;
12459:   addr_hdr.offset = HEAP_HEADER_AND_CHAIN_SLOTID;
12460: 
12461:   /* Read the header page */
12462:   vpid.volid = hfid->vfid.volid;
12463:   vpid.pageid = hfid->hpgid;
12464: 
12465:   mode = (docreate == true ? PGBUF_LATCH_WRITE : PGBUF_LATCH_READ);
12466:   addr_hdr.pgptr = pgbuf_fix (thread_p, &vpid, OLD_PAGE, mode, PGBUF_UNCONDITIONAL_LATCH);
12467:   if (addr_hdr.pgptr == NULL)
12468:     {
12469:       goto exit_on_error;
12470:     }
12471: 
12472: #if !defined (NDEBUG)
12473:   (void) pgbuf_check_page_ptype (thread_p, addr_hdr.pgptr, PAGE_HEAP);
12474: #endif /* !NDEBUG */
12475: 
12476:   /* Peek the header record */
12477:   if (spage_get_record (thread_p, addr_hdr.pgptr, HEAP_HEADER_AND_CHAIN_SLOTID, &hdr_recdes, PEEK) != S_SUCCESS)
12478:     {
12479:       goto exit_on_error;
12480:     }
12481: 
12482:   heap_hdr = (HEAP_HDR_STATS *) hdr_recdes.data;
12483:   if (VFID_ISNULL (&heap_hdr->oos_vfid))
12484:     {
12485:       if (docreate == true)
12486: 	{
12487: 	  TDE_ALGORITHM tde_algo = TDE_ALGORITHM_NONE;
12488: 
12489: 	  /* START A TOP SYSTEM OPERATION */
12490: 	  log_sysop_start (thread_p);
12491: 	  if (oos_create_file (thread_p, *hfid, heap_hdr->class_oid, *oos_vfid) != NO_ERROR)
12492: 	    {
12493: 	      log_sysop_abort (thread_p);
12494: 	      goto exit_on_error;
12495: 	    }
12496: 
12497: 	  /* Apply TDE to the new OOS file atomically with its creation.
12498: 	   * Pattern mirrors heap_ovf_find_vfid */
12499: 	  if (heap_get_class_tde_algorithm (thread_p, &heap_hdr->class_oid, &tde_algo) != NO_ERROR)
12500: 	    {
12501: 	      log_sysop_abort (thread_p);
12502: 	      goto exit_on_error;
12503: 	    }
12504: 
12505: 	  if (file_apply_tde_algorithm (thread_p, oos_vfid, tde_algo) != NO_ERROR)
12506: 	    {
12507: 	      log_sysop_abort (thread_p);
12508: 	      goto exit_on_error;
12509: 	    }
12510: 
12511: 	  /* Log undo, then redo */
12512: 	  log_append_undo_data (thread_p, RVHF_STATS, &addr_hdr, sizeof (*heap_hdr), heap_hdr);
12513: 	  VFID_COPY (&heap_hdr->oos_vfid, oos_vfid);
12514: 	  log_append_redo_data (thread_p, RVHF_STATS, &addr_hdr, sizeof (*heap_hdr), heap_hdr);
12515: 	  pgbuf_set_dirty (thread_p, addr_hdr.pgptr, DONT_FREE);
12516: 
12517: 	  log_sysop_commit (thread_p);
12518: 	}
12519:       else
12520: 	{
12521: 	  /* No OOS file exists yet; oos_vfid stays NULL. This is not an error. */
12522: 	  goto end;
12523: 	}
12524:     }
12525:   else
12526:     {
12527:       VFID_COPY (oos_vfid, &heap_hdr->oos_vfid);
12528:     }
12529: 
12530:   goto end;
12531: 
12532: exit_on_error:
12533:   success = false;
12534: 
12535: end:
12536:   if (addr_hdr.pgptr)
12537:     {
12538:       pgbuf_unfix_and_init (thread_p, addr_hdr.pgptr);
12539:     }
12540: 
12541:   return success;
12542: }
