401: vacuum_oos_find_vfid_for_heap_record (THREAD_ENTRY *thread_p, const HFID *hfid, const RECDES *record,
402: 				      PGSLOTID slotid, INT16 record_type, VFID *oos_vfid)
403: {
404:   if (!VFID_ISNULL (oos_vfid) || !heap_recdes_contains_oos (record))
405:     {
406:       return NO_ERROR;
407:     }
408:   if (heap_oos_find_vfid (thread_p, hfid, oos_vfid, false))
409:     {
410:       return NO_ERROR;
411:     }
412:   /* A record that says "I have OOS" but whose heap has no OOS file is a real problem, not a
413:    * not-yet-created file: the OOS file is always created (docreate=true) when the OOS data is
414:    * written, which happens before the flag is committed. So this means a wrongly-set flag, a
415:    * dropped OOS file, or an odd recovery ordering. We still must not fail vacuum here. Returning
416:    * ER_FAILED would restart a release-build spin in the vacuum_heap_page loop (it clears the error
417:    * and retries the same page without moving forward). Instead, log it, clear the error, and skip
418:    * OOS cleanup for this record (a small, logged leak). See commit 1bf7dda05. */
419:   {
420:     int repid_and_flags = OR_GET_INT (record->data + OR_REP_OFFSET);
421:     int record_flags = OR_GET_RECORD_FLAGS (record->data);
422:     int offset_size = OR_GET_OFFSET_SIZE (record->data);
423:     vacuum_er_log_error (VACUUM_ER_LOG_HEAP,
424: 			 "OOS flag set but no OOS VFID for hfid %d|%d slotid=%d rectype=%d rec_len=%d "
425: 			 "repid_and_flags=0x%08x record_flags=0x%02x offset_size=%d - skipping OOS cleanup "
426: 			 "(bounded leak)",
427: 			 VFID_AS_ARGS (&hfid->vfid), (int) slotid, (int) record_type,
428: 			 record->length, repid_and_flags, record_flags, offset_size);
429:   }
430:   /* TODO(do not review, remove before develop merge): force a hard crash in CI. CI runs the release
431:    * build (NDEBUG), where assert_release below only logs a notification - which the er_clear() then
432:    * wipes - so it never aborts. This case is an invariant violation (the record's OOS flag is set but
433:    * its heap has no OOS file), so abort() to surface the bug in CI instead of leaking silently. */
434:   abort ();
435:   /* In debug builds, abort so the bug that set the bad flag is caught the first time vacuum sees it.
436:    * In release builds, assert_release only records a notification error, which the er_clear() below
437:    * wipes out before we skip - so vacuum keeps running. */
438:   assert_release (false);
439:   er_clear ();
440:   VFID_SET_NULL (oos_vfid);
441:   return NO_ERROR;
442: }
