12979:   dbvalue = &value->dbvalue;
12980: 
12981:   /* fixed attribute                                                  */
12982:   /* Write the fixed attributes values, if unbound, does not matter   */
12983:   /* what value is stored. We need to set the appropriate bit in the  */
12984:   /* bound bit array for fixed attributes. For variable attributes,   */
12985:   buf->ptr = (buf->buffer
12986: 	      + OR_FIXED_ATTRIBUTES_OFFSET_BY_OBJ (buf->buffer, attr_info->last_classrepr->n_variable)
12987: 	      + value->last_attrepr->location);
