12555: 
12556:   pr_type = value->last_attrepr->domain->type;
12557:   if (pr_type == NULL)
12558:     {
12559:       return S_ERROR;
12560:     }
12561: 
12562:   dbvalue = &value->dbvalue;
12563: 
12564:   assert (dbvalue != NULL && !db_value_is_null (dbvalue));
12565: 
12566:   if (lob_create_flag == LOB_FLAG_INCLUDE_LOB && value->state == HEAP_WRITTEN_ATTRVALUE
12567:       && (pr_type->id == DB_TYPE_BLOB || pr_type->id == DB_TYPE_CLOB))
12568:     {
12569:       assert (db_value_type (dbvalue) == DB_TYPE_BLOB || db_value_type (dbvalue) == DB_TYPE_CLOB);
12570: 
12571:       elo_p = db_get_elo (dbvalue);
12572: 
12573:       if (elo_p == NULL)
12574: 	{
12575: 	  /* nothing to do here */
12576: 	  return S_SUCCESS;
12577: 	}
12578: 
12579:       if (heap_get_class_name (thread_p, &class_oid, &new_meta_data) != NO_ERROR || new_meta_data == NULL)
12580: 	{
12581: 	  return S_ERROR;
12582: 	}
12583:       save_meta_data = elo_p->meta_data;
12584:       elo_p->meta_data = new_meta_data;
12585:       {
12586: 	HFID hfid;
12587: 	char lob_path_prefix[PATH_MAX];
12588: 
12589: 	heap_hfid_cache_get (thread_p, &class_oid, &hfid, NULL, NULL);
12590: 	snprintf (lob_path_prefix, PATH_MAX, "%d%d%d%d", HFID_AS_ARGS (&hfid), value->attrid);
12591: 	rv = db_elo_copy_with_prefix (db_get_elo (dbvalue), lob_path_prefix, &dest_elo);
12592:       }
12593: 
12594:       free_and_init (elo_p->meta_data);
12595:       elo_p->meta_data = save_meta_data;
12596: 
12597:       /* The purpose of HEAP_WRITTEN_LOB_ATTRVALUE is to avoid reenter this branch. In the first pass,
12598:        * this branch is entered and elo is copied. When BUFFER_OVERFLOW happens, we need avoid to copy
12599:        * elo again. Otherwize it will generate 2 copies. */
12600:       value->state = HEAP_WRITTEN_LOB_ATTRVALUE;
12601: 
12602:       if (rv < 0)
12603: 	{
12604: 	  return S_ERROR;
12605: 	}
12606: 
12607:       pr_clear_value (dbvalue);
12608:       db_make_elo (dbvalue, pr_type->id, &dest_elo);
12609:       dbvalue->need_clear = true;
12610:     }
12611: 
12612:   length = pr_type->get_disk_size_of_value (dbvalue);
12613:   if (length > recdes->area_size)
12614:     {
12615:       recdes->area_size = length;
12616:       recdes->data = (char *) malloc (length);
12617:       if (recdes->data == NULL)
12618: 	{
12619: 	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1, (size_t) length);
12620: 	  return S_ERROR;
12621: 	}
12622:     }
12623: 
12624:   buf.ptr = buf.buffer = recdes->data;
12625:   buf.endptr = recdes->data + length;
12626:   pr_type->data_writeval (&buf, dbvalue);
12627:   recdes->length = length;
12628: 
12629:   return S_SUCCESS;
12630: }
